// ---- Projections onto the contract (what the mocks serve) ----------------------------------------------

/** The lanes (in policy order) whose task text contains the quote verbatim; the same rule the adapter applies. */
function lanesQuoting(requirement: string | null, tasks: Record<string, string>): string[] {
  if (requirement === null) return []
  return Object.keys(tasks).filter(lane => tasks[lane].includes(requirement))
}

/**
 * The review projection at contract 1.4.0. A section without `reviewers` (exports before 1.4.0) is one reviewer named
 * `review`: the adapter fills a one-entry list from the section itself and tags every finding with that id, so the viewer
 * has a single code path. The combined `reviewer` identity stays what the review node names (the first reviewer's session).
 */
function projectReview(runId: string, section: RawReviewSection, tasks: Record<string, string>): ReviewResult {
  const link = (finding: RawFinding, reviewer: string) => ({ ...finding, reviewer: finding.reviewer ?? reviewer, requirement_found_in: lanesQuoting(finding.requirement, tasks) })
  const reviewers: RawReviewer[] = section.reviewers ?? [{
    reviewer_id: DEFAULT_REVIEWER_ID, transport: section.transport, session_id: section.reviewer_session_id, verdict: section.verdict,
    findings: section.findings, launched_at: null, accepted_at: section.reviewed_at, status: section.verdict === 'approved' ? 'accepted' : 'blocked',
  }]
  return validateReviewResult({
    contract_version: REVIEW_CONTRACT_VERSION, run_id: runId, node_id: 'review', attempt: section.attempt,
    reviewer: { session_id: section.reviewer_session_id, transport: section.transport, independent: true },
    bundle_sha256: section.bundle_sha256, candidate_commit: section.candidate_commit, verdict: section.verdict,
    findings: section.findings.map(finding => link(finding, DEFAULT_REVIEWER_ID)),
    reviewers: reviewers.map(reviewer => ({
      reviewer_id: reviewer.reviewer_id, transport: reviewer.transport, session_id: reviewer.session_id, verdict: reviewer.verdict,
      findings: reviewer.findings.map(finding => link(finding, reviewer.reviewer_id)),
      launched_at: reviewer.launched_at === null ? null : zulu(reviewer.launched_at),
      accepted_at: reviewer.accepted_at === null ? null : zulu(reviewer.accepted_at),
      status: reviewer.status,
    })),
    reviewed_at: zulu(section.reviewed_at),
    diff: section.diff === null ? null : { artifact_id: REVIEW_DIFF_ARTIFACT_ID, kind: 'patch', uri: `${apiRunPath(runId, runDetails[runId].summary.workflow_id)}/artifacts/${REVIEW_DIFF_ARTIFACT_ID}`, sha256: section.diff.sha256 },
  })
}

/**
 * The run-inputs projection at the current contract. A 1.2.0 export has neither a selection nor pinned check kinds: every
 * listed lane was selected, nothing was excluded, and the kinds are the ones its role required, exactly as the adapter serves it.
 */
function projectInputs(runId: string, section: RawInputsSection): RunInputs {
  return validateRunInputs({
    contract_version: INPUTS_CONTRACT_VERSION, run_id: runId, feature: section.feature, base_commit: section.base_commit, source_branch: section.source_branch,
    mode: section.mode, automatic: section.automatic,

    optional = {key: item.get(key) if isinstance(item.get(key), str) else None for key in ("session_id", "observed_state", "background_id")}
    started = item.get("native_started_at")
    return {"session_id": optional["session_id"], "launch_token": item["launch_token"], "launch_requested_at": zulu(item["launch_requested_at"]),
            "native_started_at": started if type(started) is int else None, "observed_state": optional["observed_state"],
            "status": item["status"], "launcher_invocations": item["launcher_invocations"], "background_id": optional["background_id"]}


def optional_text(value) -> str | None:
    return value if isinstance(value, str) and value.strip() else None


def completion_signal(item) -> dict | None:
    """The worker's completion file; the 1.1.0 evidence is null when the file is 1.0.0 (or leaves a field empty)."""
    if (not isinstance(item, dict) or item.get("status") not in {"completed", "blocked", "question"} or not isinstance(item.get("summary"), str)
            or not item["summary"].strip() or not string_list(item.get("open_assumptions"))):
        return None
    untested = item.get("untested")
    return {"status": item["status"], "summary": item["summary"], "open_assumptions": list(item["open_assumptions"]),
            "untested": list(untested) if isinstance(untested, list) and all(isinstance(entry, str) for entry in untested) else None,
            "falsifying_check": optional_text(item.get("falsifying_check")), "verify_yourself": optional_text(item.get("verify_yourself"))}


QUESTION_KEYS = ("n", "question", "asked_at", "answer", "answered_at")


def worker_questions(path: Path) -> list:
    """`<node>.questions.json` as `{n, question, asked_at, answer, answered_at}` entries; `[]` when absent or malformed."""
    item = load_optional(path)
    questions = item.get("questions") if isinstance(item, dict) else None
    if not isinstance(questions, list):
        return []
    result = []
    for entry in questions:
        if (not isinstance(entry, dict) or type(entry.get("n")) is not int or not optional_text(entry.get("question"))
                or not isinstance(entry.get("asked_at"), str) or not (entry.get("answer") is None or isinstance(entry.get("answer"), str))
                or not (entry.get("answered_at") is None or isinstance(entry.get("answered_at"), str))
                or (entry.get("answer") is None) != (entry.get("answered_at") is None)):
            return []
        result.append({key: entry.get(key) for key in QUESTION_KEYS})
    return result


def challenge_section(directory: Path) -> dict | None:
    """The latest `challenge.json` without `run_id` and `version`, plus `attempts`; null when absent or invalid."""
    item = load_optional(directory / "challenge.json")
    if item is None:
        return None
    from jsonschema.exceptions import ValidationError
    from .verification import validate_schema
    try:
        validate_schema("challenge", item)
    except ValidationError:
        return None
    section = {key: value for key, value in item.items() if key not in {"run_id", "version"}}
    section["attempts"] = item["attempt"]
    return section


def accepted_handoff(item) -> dict | None:
    if not isinstance(item, dict) or not isinstance(item.get("summary"), str) or not item["summary"].strip() or not string_list(item.get("open_assumptions")):
        return None
    return {"summary": item["summary"], "open_assumptions": list(item["open_assumptions"])}


def stop_confirmation(path: Path) -> dict | None:
    item = load_optional(path)
    if not isinstance(item, dict) or not isinstance(item.get("stopped"), bool):
        return None
    return {"stopped": item["stopped"], "confirmed_at": utc(path.stat().st_mtime) if item["stopped"] else None}


def worker_inputs(directory: Path, plan: dict, policy: dict, worker: dict) -> dict:
    node = worker["node_id"]
    prompt = directory / f"{node}.prompt.txt"
    return {"role": worker["role"], "required_check_kinds": required_kinds(policy, worker), "task": plan["nodes"][node]["task"],
            "prompt": prompt.read_text() if prompt.is_file() and not prompt.is_symlink() else None,
            "owned_paths": list(worker["owned_paths"]),
            "checks": [{"id": check["id"], "kind": check["kind"], "argv": list(check["argv"]), "command": shlex.join(check["argv"]),
                        "timeout_seconds": check["timeout_seconds"],
                        "scenarios": [{"id": scenario["id"], "description": scenario["description"]} for scenario in check["scenarios"]]}
                       for check in worker["checks"]],
            "launch": launch_receipt(load_optional(directory / f"{node}.interactive.json")),
            "completion": completion_signal(load_optional(directory / f"{node}.completion.json")),
            "handoff": accepted_handoff(load_optional(directory / f"{node}.handoff.json")),
            "stop": stop_confirmation(directory / f"{node}.stop.json"),
            "questions": worker_questions(directory / f"{node}.questions.json")}


def inputs_section(directory: Path, plan: dict, policy: dict) -> dict:
    automatic = plan.get("automatic")
    workers = plan_workers(plan)
    declared = [worker["node_id"] for worker in policy["workers"]]
    if not set(workers) <= set(declared):
        raise ValueError("Plan selects lanes the pinned policy does not declare")
    return {"feature": policy["feature"], "policy_version": policy["version"], "base_commit": plan["base_commit"],
            "source_branch": plan.get("source_branch"), "mode": "automatic" if automatic else "manual",
            "automatic": None if not automatic else {
                "finish": automatic["finish"], "permission_mode": automatic["permission_mode"],
                "worker_timeout_seconds": automatic["worker_timeout_seconds"], "review_timeout_seconds": automatic["review_timeout_seconds"],
                # Plans pinned before the setting: the transport the receipts record, null before any reviewer ran.
                "reviewer_transport": automatic["reviewer_transport"] if "reviewer_transport" in automatic else recorded_transport(directory)},

def wait_handoffs(runtime, *, clock=time.time, sleep=time.sleep) -> None:
    """Idle alone never means completion. Deadlines survive controller restart.

    A 1.1.0 `question` completion pauses only that lane's deadline (persisted in `<node>.deadline.json`) until the
    operator answers, with `workflow answer` or by typing in the pane; the other lanes keep running.
    """
    from .guardrails import PANE_ANSWER, deadline_extension, load_questions, record_answer, record_question, waiting_question
    validate_automatic(runtime.plan)
    workers = lanes(runtime)
    if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
        # Recover a controller crash after durable handoffs/stop intent, before snapshot.
        for node in workers:
            if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
                raise RuntimeError("Handoff changed after stop intent")
        return
    attention: set[str] = set()
    # Answers recorded before this controller started need no second event.
    answered = {(node, entry["n"]) for node in workers for entry in load_questions(runtime.directory, node) if entry["answer"] is not None}
    while True:
        rows = runtime.sessions.inventory()
        handoffs = {}
        for node in workers:
            receipt = read_json(runtime.directory / f"{node}.interactive.json")
            started = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
            extension = deadline_extension(runtime.directory, node)  # None while a question waits: that lane has no running deadline.
            if extension is not None and clock() >= started + runtime.plan["automatic"]["worker_timeout_seconds"] + extension:
                raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError("Native worker missing; reconciliation required")
            if row["state"] == "working" and waiting_question(runtime.directory, node):
                # The operator typed the answer in the pane: the worker is working again, so its deadline runs again.
                record_answer(runtime.directory, node, PANE_ANSWER, clock)
            for entry in load_questions(runtime.directory, node):
                if entry["answer"] is not None and (node, entry["n"]) not in answered:
                    answered.add((node, entry["n"]))
                    runtime.event(node, "interactive", f"Worker {node} question {entry['n']} answered; its deadline runs again")
            if row["state"] == "blocked" and node not in attention:
                # A native session reports `blocked` when its turn ended needing a human: a question,
                # a permission prompt or a refusal the harness could not continue past. That is not a
                # failure of the lane, and the other lanes keep working. The operator may answer in the
                # pane; the worker deadline bounds the wait. No billing/provider fallback.
                attention.add(node)
                runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); "
                                                   "waiting until its deadline")
            elif row["state"] != "blocked":
                attention.discard(node)
            path = runtime.directory / f"{node}.completion.json"
            if row["state"] in {"idle", "done"} and path.exists():
                if read_signal(runtime, node)["status"] == "question":
                    record_question(runtime, node, read_signal(runtime, node), clock)
                    continue
                handoffs[node] = read_completion(runtime, node)
        if set(handoffs) == set(workers):
            for node, value in handoffs.items():
                save_json(runtime.directory / f"{node}.handoff.json", value)
            return
        sleep(2)


# Finding attributions that name no single lane; the run's lane ids complete the vocabulary.
FINDING_ATTRIBUTIONS = ("multiple", "none")


def finding_workers(runtime) -> list[str]:
    """The `worker` vocabulary of this run's findings: its lane ids, then multiple and none."""
    return [*lanes(runtime), *FINDING_ATTRIBUTIONS]


def worker_vocabulary(runtime) -> str:
    """How the prompts spell the vocabulary: `ui, adapter, multiple or none`."""
    words = finding_workers(runtime)
    return ", ".join(words[:-1]) + " or " + words[-1]


def review_schema(runtime) -> dict:
    """The structured-output schema of the print-mode reviewer, generated from the run's lanes."""
    return {
        "type": "object", "additionalProperties": False, "required": ["verdict", "findings"],
        "properties": {
            "verdict": {"enum": ["approved", "blocked"]},
            "findings": {"type": "array", "items": {
                "type": "object", "additionalProperties": False,
                "required": ["severity", "message", "disposition", "worker", "requirement"],
                "properties": {"severity": {"enum": ["P0", "P1", "P2"]}, "message": {"type": "string", "minLength": 1},

pending = [item.value.get("kind") for task in state.tasks for item in task.interrupts]
value = None
